public class OrderService {
    private final OrderRepository repository;
    private final int maxRetries;

    @Autowired  // Injection: constructor injection (preferred)
    public OrderService(OrderRepository repository, 
                        @Value("${order.max-retries:3}") int maxRetries) {
        this.repository = repository;
        this.maxRetries = maxRetries;
    }

    @PostConstruct  // Lifecycle: runs after dependency injection
    public void init() {
        System.out.println("OrderService initialized with " + maxRetries + " retries");
    }
}

