@Configuration
public class DataSourceConfig {

    @Bean
    @Profile("dev")  // Only created when dev profile is active
    public DataSource devDataSource() {
        var ds = new EmbeddedDatabaseBuilder()
                .setType(EmbeddedDatabaseType.H2)
                .addScript("classpath:schema.sql")
                .build();
        System.out.println("Using H2 in-memory database for dev");
        return ds;
    }

    @Bean
    @Profile("prod")  // Only created when prod profile is active
    public DataSource prodDataSource() {
        var ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:postgresql://prod-db.example.com:5432/appdb");
        ds.setUsername("produser");
        ds.setPassword(System.getenv("DB_PASSWORD"));  // From environment variable
        ds.setMaximumPoolSize(20);
        System.out.println("Using PostgreSQL production database");
        return ds;
    }

    @Bean
    @Profile("test")  // Only for integration tests
    public DataSource testDataSource() {
        return new EmbeddedDatabaseBuilder()
                .setType(EmbeddedDatabaseType.H2)
                .build();
    }
}
