// Custom condition checking if running in production
class ProductionCondition implements Condition {
    @Override
    public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {
        var env = context.getEnvironment();
        return "production".equals(env.getProperty("spring.profiles.active"));
    }
}

@Configuration
class CacheConfiguration {

    @Bean
    @Conditional(ProductionCondition.class)  // Only in production
    public CacheManager redisCacheManager() {
        return new RedisCacheManager();
    }

    @Bean
    @ConditionalOnMissingBean(CacheManager.class)  // Fallback if no other CacheManager
    public CacheManager simpleCacheManager() {
        return new SimpleCacheManager();
    }

    @Bean
    @ConditionalOnClass(name = "com.fasterxml.jackson.databind.ObjectMapper")  // If Jackson on classpath
    @ConditionalOnProperty(name = "app.json.enabled", havingValue = "true")  // AND property is true
    public ObjectMapper objectMapper() {
        return new ObjectMapper();
    }
}
