@Service
public class OrderService {

    private final OrderRepository orderRepo;
    private final InventoryRepository inventoryRepo;

    public OrderService(OrderRepository orderRepo, InventoryRepository inventoryRepo) {
        this.orderRepo = orderRepo;
        this.inventoryRepo = inventoryRepo;
    }

    @Transactional  // Both DB operations in one transaction
    public void placeOrder(Long productId, int quantity) {
        var inventory = inventoryRepo.findById(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));

        if (inventory.getStock() < quantity) {
            throw new InsufficientStockException();  // Rolls back, no order created
        }

        inventory.reduceStock(quantity);
        inventoryRepo.save(inventory);

        var order = new Order(productId, quantity, LocalDateTime.now());
        orderRepo.save(order);  // If this fails, inventory change is rolled back
    }

    @Transactional(readOnly = true)  // Optimization for read-only queries
    public List<Order> getUserOrders(Long userId) {
        return orderRepo.findByUserId(userId);
    }

    @Transactional(rollbackFor = Exception.class)  // Roll back on checked exceptions too
    public void processPayment(Order order) throws PaymentException {
        // Payment logic that might throw checked PaymentException
    }
}
